    @Test
    void additionalToolPolicyPreservesDefinitionContractInsideConfiguredWorkspace() {
        WorkspaceProvider.WorkspaceIdentity workspace = new WorkspaceProvider.WorkspaceIdentity("workspace-1", 0);
        ToolDefinition allowed = ToolDefinition.sync(
                "stage6-blocking", "resident effect", Map.of("type", "object"),
                (arguments, cancellation) -> ToolDefinition.ToolResult.text("done")).alwaysAllow();
        ToolExecutionPolicy policy = JiCli.workspaceToolPolicy(workspace, List.of(allowed));
        var context = new ToolExecutionPolicy.Context(
                "host-1", "session-1", "actor-1", "hcp", workspace, "call-1",
                allowed.schema().name(), Map.of(), 0, java.time.Instant.parse("2026-09-07T00:00:00Z"));

        var evaluation = policy.evaluate(context);

        assertEquals(ToolExecutionPolicy.Action.ALLOW, evaluation.action());
        assertEquals(allowed.sequential(), evaluation.sequential());
        assertEquals(PermissionDecider.RiskLevel.LOW, evaluation.riskLevel());
        assertEquals("additional-tool-definition", evaluation.ruleId());
        assertEquals(ToolExecutionPolicy.Action.DENY, policy.evaluate(new ToolExecutionPolicy.Context(
                "host-1", "session-1", "actor-1", "hcp",
                new WorkspaceProvider.WorkspaceIdentity("workspace-2", 0), "call-2",
                allowed.schema().name(), Map.of(), 0,
                java.time.Instant.parse("2026-09-07T00:00:00Z"))).action());
        assertEquals(ToolExecutionPolicy.Action.DENY, policy.evaluate(new ToolExecutionPolicy.Context(
                "host-1", "session-1", "actor-1", "hcp", workspace, "call-3", "unknown",
                Map.of(), 0, java.time.Instant.parse("2026-09-07T00:00:00Z"))).action());
    }

